import {uncertaintyState} from './uncertainty-examples.js?v=0.31.0';
import {activeExplorationActions,toggleGuideFamily,selectCareer,createPlanActions,applyGuidePay} from './guide-state.js?v=0.31.0';
import {explorationHistoryPanel} from './guide-ui.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
export function transitionExampleState(){const s=uncertaintyState('mixed'),steps=activeExplorationActions(s);Object.assign(steps[0],{done:true,dueDate:'2026-11-01',detail:'Make a biology poster with a teacher and ask for one revision.',notice:'I enjoyed turning biology into a clear picture. I want to try graphic design.'});Object.assign(steps[1],{done:true,notice:'I liked understanding the topic, but making the poster held my interest longer.'});toggleGuideFamily(s,'health');s.guide.pathIds=['design','visual-arts'];s.guide.path='design';s.guide.taskInterests=['work:graphic-design'];selectCareer(s,'graphic-design');s.guide.preparation='Graphic design';s.guide.salaryPicked=true;applyGuidePay(s);createPlanActions(s);return s;}
export function transitionExamplePage(){const s=transitionExampleState();return `<div class="page-intro"><div><span class="eyebrow">A FICTIONAL STUDENT’S NEXT CHAPTER</span><h1>A new focus. The same story.</h1><p>Read-only example. Your own answers and plan stay yours.</p></div></div><div class="guide-fact-grid transition-stages"><article><b>Explore</b><p>Creative work + health</p></article><article><b>Try</b><p>Two activities. Two sets of notes.</p></article><article><b>Choose</b><p>Graphic design</p></article></div><section class="guide-input-panel"><h2>What changed?</h2><p>The student enjoyed making a biology poster more than researching the health topic. They chose graphic design as a direction to explore further.</p><p><strong>Their earlier health interest is still here.</strong> So are the completed activities, notes, edited instructions, and target date.</p><p>Written reflections are saved in the student’s own words. They are not automatically scored into a career match.</p></section>${explorationHistoryPanel(s,{readOnly:true})}<section class="personal-plan-section"><span class="overline">MY CAREER PLAN · GRAPHIC DESIGN</span><h2>Three next steps for this direction.</h2><p>Explore a graphic design or visual communication degree, build a portfolio, and compare affordable programs.</p>${s.actions.filter(a=>a.careerId==='graphic-design').map(a=>`<article class="personal-action"><h3>${h(a.title)}</h3><p>${h(a.detail)}</p></article>`).join('')}<p><a href="#/career/graphic-design">Education, requirements, pay & Austin lifestyle →</a></p></section><details class="more-info"><summary>What we tested</summary><p>An older saved exploration draft was reopened, given activity notes, narrowed to design, and taken through preparation, salary/lifestyle, and a career plan. Reopening and real plan exports preserved all three earlier steps and all thirty original answers.</p><p>A 1,620-character browser-entered note survived intact. Regression checks cover every supported 2,000-character observation field, changing careers, restarting from Start, full-draft restoration, and returning to exploration.</p><p>These are synthetic usability and data-preservation checks, not predictive career validation.</p></details><p><a href="#/student-examples/career-switch">What if this student switches to medicine? →</a></p><p><a href="#/student-examples/mixed">Back to the original mixed-interest student →</a></p>`;}
